-- Iridium Ink — Neovim
-- Generated by build-tokens.py. Do not edit; edit the palette and re-run.
--
-- Install: drop this at ~/.config/nvim/colors/iridium-ink.lua, then
--   vim.opt.termguicolors = true
--   vim.cmd.colorscheme("iridium-ink")
--
-- Every group also carries a cterm index, chosen as the nearest ANSI slot by
-- dE2000, so the theme degrades rather than disappears without termguicolors.
-- It is still a much poorer thing: 16 colours cannot hold six distinct stops.

vim.cmd("highlight clear")
if vim.fn.exists("syntax_on") == 1 then
  vim.cmd("syntax reset")
end
vim.o.background = "dark"
vim.g.colors_name = "iridium-ink"

local hl = vim.api.nvim_set_hl

